import 'package:flutter/widgets.dart';

import '../engine/pastra_ai.dart';
import '../engine/rules.dart';
import '../game/app_settings.dart';
import 'progress_strings.dart';
import 'translations.dart';

/// All user-visible text. The texts live in [kTranslations] (generated by
/// tool/l10n/gen.py); a missing text falls back to English.
class Strings {
  final String lang;

  const Strings(this.lang);

  static Strings of(BuildContext context) => Strings(SettingsScope.of(context).language);

  /// The language's own name ("Ελληνικά", "Türkçe", …).
  static String languageName(String code) => kLanguageNames[code] ?? code;

  String _s(String key, [Map<String, Object> args = const <String, Object>{}]) {
    var text = kTranslations[lang]?[key] ?? kTranslations['en']![key] ?? key;
    args.forEach((name, value) => text = text.replaceAll('{$name}', '$value'));
    return text;
  }

  // ------------------------------------------------------------- general
  String get appTitle => _s('appTitle');
  String get appSubtitle => _s('appSubtitle');
  String get continueGame => _s('continueGame');
  String get newGame => _s('newGame');
  String get play => _s('play');
  String get playOffline => _s('playOffline');
  String get playOnline => _s('playOnline');
  String get playOfflineHint => _s('playOfflineHint');
  String get playOnlineHint => _s('playOnlineHint');
  String get rules => _s('rules');
  String get settings => _s('settings');
  String get statistics => _s('statistics');
  String get onlineSoon => _s('onlineSoon');
  String get cancel => _s('cancel');
  String get ok => _s('ok');
  String get delete => _s('delete');
  String stats(int won, int played) => _s('stats', <String, Object>{'won': won, 'played': played});

  // ------------------------------------------------------------ new game
  String get gameType => _s('gameType');
  String get mode1v1 => _s('mode1v1');
  String get mode2v2 => _s('mode2v2');
  String get mode1v1Hint => _s('mode1v1Hint');
  String get mode2v2Hint => _s('mode2v2Hint');
  String get difficulty => _s('difficulty');
  String level(AiLevel value) {
    if (value == AiLevel.easy) return _s('levelEasy');
    if (value == AiLevel.medium) return _s('levelMedium');
    return _s('levelHard');
  }

  String get start => _s('start');
  String targetInfo(GameVariant variant, int target, int perDeal) => _s(
        'targetInfo',
        <String, Object>{'variant': variantName(variant), 'target': target, 'perDeal': perDeal},
      );

  String variantName(GameVariant v) => v == GameVariant.pile ? _s('variantPile') : _s('variantSums');

  String variantHint(GameVariant v) => v == GameVariant.pile ? _s('variantPileHint') : _s('variantSumsHint');

  // ---------------------------------------------------------------- game
  String get you => _s('you');
  String get us => _s('us');
  String get them => _s('them');
  String get partner => _s('partner');

  /// How many bot names there are (the same in every language).
  static int get botNameCount => kBotNames['en']!.length;

  String botName(int index) {
    final names = kBotNames[lang] ?? kBotNames['en']!;
    return names[index < 0 ? 0 : index % names.length];
  }

  String get yourTurn => _s('yourTurn');
  String playing(String name) => _s('playing', <String, Object>{'name': name});
  String get thinking => _s('thinking');
  String get tapAgain => _s('tapAgain');
  String get dragHint => _s('dragHint');
  String get dropToPlay => _s('dropToPlay');
  String get rotatePhone => _s('rotatePhone');
  String get kapakAlti => _s('kapakAlti');
  String takes(int n) => n == 1 ? _s('takes1') : _s('takesN', <String, Object>{'n': n});
  String get staysOnTable => _s('staysOnTable');
  String get goesOnPile => _s('goesOnPile');
  String get takesPile => _s('takesPile');
  String get jackTakesPile => _s('jackTakesPile');
  String get jackSweeps => _s('jackSweeps');
  String get pastraBanner => _s('pastraBanner');
  String plusPoints(int n) => '+$n';
  String deck(int n) => _s('deck', <String, Object>{'n': n});
  String round(int n) => _s('round', <String, Object>{'n': n});
  String target(int n) => _s('target', <String, Object>{'n': n});
  String cards(int n) => n == 1 ? _s('cards1') : _s('cardsN', <String, Object>{'n': n});
  String pastras(int n) => n == 1 ? _s('pastras1') : _s('pastrasN', <String, Object>{'n': n});
  String leftoversTo(String name) => _s('leftoversTo', <String, Object>{'name': name});
  String get lastDeal => _s('lastDeal');
  String levelN(int n) => _s('levelN', <String, Object>{'n': n});
  String get tournament => _s('tournament');
  String get tournamentHint => _s('tournamentHint');
  String get quickGame => _s('quickGame');
  String get quickGameHint => _s('quickGameHint');
  String get roundQF => _s('roundQF');
  String get roundSF => _s('roundSF');
  String get roundFinal => _s('roundFinal');
  String tournamentRound(int round) => round == 0 ? roundQF : (round == 1 ? roundSF : roundFinal);
  String get playMatch => _s('playMatch');
  String vsName(String name) => _s('vsName', <String, Object>{'name': name});
  String get championMsg => _s('championMsg');
  String eliminatedMsg(String round) => _s('eliminatedMsg', <String, Object>{'round': round});
  String get newTournament => _s('newTournament');
  String tournamentBonus(int n) => _s('tournamentBonus', <String, Object>{'n': n});
  String get leaveMatchBody => _s('leaveMatchBody');
  String get leaderboardShow => _s('leaderboardShow');
  String get fullscreen => _s('fullscreen');
  String get exitFullscreen => _s('exitFullscreen');
  String get fullscreenIos => _s('fullscreenIos');
  String get levelUp => _s('levelUp');
  String unlocksAt(int n) => _s('unlocksAt', <String, Object>{'n': n});
  String get newColors => _s('newColors');
  String quadBy(String name) => _s('quadBy', <String, Object>{'name': name});
  String get quadRedeal => _s('quadRedeal');
  String get leaveTitle => _s('leaveTitle');
  String get leaveBody => _s('leaveBody');
  String get leave => _s('leave');

  // ------------------------------------------------------- round summary
  String roundOver(int n) => _s('roundOver', <String, Object>{'n': n});
  String get mostCards => _s('mostCards');
  String get aces => _s('aces');
  String get jacks => _s('jacks');
  String get honours => _s('honours');
  String get twoOfClubs => _s('twoOfClubs');
  String get tenOfDiamonds => _s('tenOfDiamonds');
  String get pastraRow => _s('pastraRow');
  String get roundTotal => _s('roundTotal');
  String get gameScore => _s('gameScore');
  String get nextRound => _s('nextRound');
  String get youWon => _s('youWon');
  String get youLost => _s('youLost');
  String get teamWon => _s('teamWon');
  String get teamLost => _s('teamLost');
  String get playAgain => _s('playAgain');
  String get mainMenu => _s('mainMenu');

  // ------------------------------------------------------------ settings
  String get language => _s('language');
  String get yourName => _s('yourName');
  String get gameRules => _s('gameRules');
  String get targetScore => _s('targetScore');
  String get cardsPerDeal => _s('cardsPerDeal');
  String get jackSweepIsPastra => _s('jackSweepIsPastra');
  String get jackSweepIsPastraHint => _s('jackSweepIsPastraHint');
  String get jackOnJack => _s('jackOnJack');
  String get jackOnLoneCardIsPastra => _s('jackOnLoneCardIsPastra');
  String get jackOnLoneCardIsPastraHint => _s('jackOnLoneCardIsPastraHint');
  String get variant => _s('variant');
  String get nothing => _s('nothing');
  String get pastraOnLastCard => _s('pastraOnLastCard');
  String get pastraOnLastCardHint => _s('pastraOnLastCardHint');
  String get gameplay => _s('gameplay');
  String get fastAnimations => _s('fastAnimations');
  String get haptics => _s('haptics');
  String get sound => _s('sound');
  String get turnTime => _s('turnTime');
  String get turnTimeHint => _s('turnTimeHint');
  String get noLimit => _s('noLimit');
  String seconds(int n) => _s('seconds', <String, Object>{'n': n});
  String get resetRules => _s('resetRules');
  String get rulesApplyToNewGames => _s('rulesApplyToNewGames');
  String points(int n) => _s('points', <String, Object>{'n': n});
  String get about => _s('about');
  String get aboutBody => _s('aboutBody');

  // ---------------------------------------------------------- statistics
  String get statGames => _s('statGames');
  String get statWins => _s('statWins');
  String get statWinRate => _s('statWinRate');
  String get statStreak => _s('statStreak');
  String get statBestStreak => _s('statBestStreak');
  String get statPastras => _s('statPastras');
  String get statJackPastras => _s('statJackPastras');
  String get statBestRound => _s('statBestRound');
  String get statRounds => _s('statRounds');
  String get stat1v1 => _s('stat1v1');
  String get stat2v2 => _s('stat2v2');
  String get statByLevel => _s('statByLevel');
  String get resetStats => _s('resetStats');
  String get resetStatsConfirm => _s('resetStatsConfirm');
  String get noStats => _s('noStats');

  // ---------------------------------------------- achievements & looks
  String get achievements => _s('achievements');
  String get achUnlocked => _s('achUnlocked');
  String achTitle(String id) => ProgressStrings(lang).achTitle(id) ?? _s('ach_${id}_t');
  String achDesc(String id) => ProgressStrings(lang).achDesc(id) ?? _s('ach_${id}_d');
  String achCount(int n, int total) => _s('achCount', <String, Object>{'n': n, 'total': total});
  String get appearance => _s('appearance');
  String get tableColor => _s('tableColor');
  String get cardBackLabel => _s('cardBackLabel');
  String get credits => _s('credits');

  // ------------------------------------------------------------ tutorial
  String get tutorial => _s('tutorial');
  String get tutorialNext => _s('tutorialNext');
  String get tutorialSkip => _s('tutorialSkip');
  String get tutorialDone => _s('tutorialDone');
  String get tutorialQueued => _s('tutorialQueued');
  String tutorialTitle(String step) => _s('tut_${step}_t');
  String tutorialBody(String step) => _s('tut_${step}_b');

  // --------------------------------------------------------------- rules
  /// (title, body) sections of the rules screen.
  List<List<String>> rulesSections(GameVariant v) {
    final key = v == GameVariant.pile ? 'pile' : 'sums';
    return kRules[lang]?[key] ?? kRules['en']![key]!;
  }
}
